「理由はあるのだと思いますが……それが何なのかはわかりません。今直面している問題は深刻なものではありますが、すぐに動かなければならないものではないですし。もしかしたらそろそろ事態が動くのかも知れなくて、それに備えてのことかも知れません」<br>
　言いながら一瞬絡んだ視線は、露骨に逸らされた。<br>
「……ほう」<br>
　先程と言い、今と言い、この態度。彼女は本当に私の召喚を望んでいなかったようだ。随分嫌われたものだが、私の知る限りこの者は滅多に人を嫌わぬ。心清く穏やかな彼女の珍しい一面を引き出せたのは、いっそ愉快にすら思う。<br>
