「では、戻るまでの間よろしく頼む。“選ばれし者”よ。……フフ」<br>
<br>
◆―――……サザントスとミトスの語らい<br>
　“追憶”として共に行動するようになり驚いたのが、こちらの世界の私は既にいなくなっているということだった。<br>
