    keywords: `FF4 × オクトパストラベラー大陸の覇者コラボ
  「フッ……！　ハァ！！」<br>
　凪ぐように振るい、返る力を利用して前方に踏み込みながら鋭く突く。<br>
　槍を使った経験は多くない。にも関わらず、こうして構えれば次にどう動けばいいのかわかる。これがクリスタルの…“竜騎士”とやらの力か。<br>
　広域を砕く閃槍はさながら竜の顎が如く、反撃を許さぬ連撃は怒れる竜の爪牙が如く。いずれもこちらの世界では見られぬ槍術だ。<br>
　中でも風を供とし天空より見舞う一撃は強力だが…、『槍は商人が身を守るための武器』または『集団戦における一般兵の装備』として認知されているこの大陸では、広めるのは難しいだろう。<br>
　跳躍自体もそうだが、跳躍後の体勢を維持するために求められる筋力は、剣士のそれと異なる。それに、天空より定めた狙いを過たずに穿つための機を読む力とセンス。跳躍時、および襲撃時の補助を目的とした風使いの技術。襲撃後、次の行動に移るための体捌き。いずれが欠けてもこの技は成せぬ。<br>
　一子相伝の奥義として伝えられても不思議ではない。私もクリスタルの力無しに習得しようとすれば、最低数年は費やすことになるだろう。<br>
　世が窮している現状を思えば簡単には喜べぬが、こうして戦いの手数を増やせるのはありがたい。畏孵とやらが呼び寄せた異界の力、その身を以て味わわせてやろうではないか。<br>
　しかし、身体の線に合わせたような鎧は防御面で不安を覚える。『ジャンプ』の邪魔をしないための工夫であるとのことだが、それならばこの頭装備は無い方が良いのではないか、と問えば――<br>
<br>
「それは竜騎士の証のようなものだから」<br>
<br>
　と返され外すことは叶わなかった。<br>
　セシルがいた異界や国について未だ詳しく知れていないが、伝統や様式美を重んじるところがあるのだろう。<br>
　…まあ、狙いを定めている際に髪が広がるのを抑えるのに役立っていることもある。今しばらくはこのままで良かろう。<br>
　否、外せぬのなら……気にすることがなくなるよう、己が一部としてしまえば良い。要は慣れだ。<br>
<br>
―――――……<br>
―――……<br>
――…<br>
<br>
　焚火が揺れる音だけが響く夜更け。目を閉じたまま周囲を探れば、落ち着いた気配が三つと、薄く緊張を保つ気配が一つ。<br>
　――頃合いだろう。<br>
　皆の眠りを妨げぬように身体を起こせば、火の番をしているセイルと目が合った。<br>
「あれ？　サザントス、交代までまだ時間あるけど」<br>
「鍛錬だ」<br>
　声を抑えて問いかけてくるセイルにそう返せば、気遣わしげに眉を寄せられた。<br>
「大丈夫？　このあとの火の番、サザントスだけど……」<br>
「心配せずとも必要な休息はとれている。…交代の時間までには戻る、異変があれば呼べ」<br>
「わかった。気を付けて」<br>
　心正しく素直な少年――セイル。“選ばれし者”であるこの少年の活躍を、私はよく知っている……のだが、セイルが言うにはこれも畏孵の断片の影響であるらしい。<br>
　セシルが異界の者だと言うのはわかるが、私とオフィーリア、セイルとアグネアでまた出身世界が異なるのだと聞いた時は驚きを隠せなかった。<br>
　厄介なことだ。違和感は異変を探るのに欠かせぬと言うのに、その違和感を抱かぬようにされては……最悪、誰も異変に気付けぬままこの世は混沌に呑まれてしまう。<br>
　唯一、聖火神の指輪を持つセイルだけは断片の影響を受けぬようで、調査は彼頼みになってしまっている。ただでさえあの者はこの世の闇を払う任を託されていると言うのに、これ以上負担を増やすわけにはゆかぬ。<br>
　……否、彼ではないのだったな。私が本来知る“選ばれし者”は。<br>
「一刻も早く、大陸を元に戻さねば」<br>
　そのために、出来る全てを。<br>
　調査がセイル頼みとなるならば、その他の――例えば戦闘を、私が担えば良い。<br>
　セイルは剣を使うが戦いをどこか恐れている節がある、逆に私は戦うのが仕事とも言える。得手不得手がはっきりしているのだ、互いに補えばいい。<br>
「……この辺りで良いか」<br>
　野営地から離れた林の中、葉の間から差し込む月の光だけが闇を僅かに遠ざけている。周囲に魔物らしき気配はない。<br>
　軽く体をほぐしたあと、後端、中央、穂先近くと、持つ場所を変えながら手の中で槍を回してみる。己の一部と言えるほどではないが、見ずに取り回すくらいならば造作もない。こうして特に意識せずとも槍を弄べるのは“竜騎士”の力によるものだ。<br>
　だが、この異界の力に頼りきるつもりは無い。槍を己の一部、腕の延長だと思えるよう鍛錬を積まなければ。<br>
　槍は剣よりも間合いが広い、つまり狭い場所では振るうのに難がある。木々が乱立する中での鍛錬は良い経験となるだろう。<br>
「―――ふっ！」<br>
　試しに円を描くように振れば、槍は前方の幹を抉り、後方の幹は切っ先が掠るに留まった。狙い通りに振れている。<br>
　間合いに問題はない、振ったあとの動作からも無駄をなくせている。<br>
　今度はさらに力を込めて、同じ場所を薙ぐように。<br>
「はっ！」<br>
　振るった穂先に風が逆巻く。もっと勢いを付ければこれを利用した追撃が見込めそうだ。<br>
「ならばもう一度……！」<br>
　裂いた先で風が吹き荒れるイメージを持ちながら――<br>
「はぁっ！！」<br>
　渾身の力で振り抜いたその軌跡を追うように風が荒々しく駆け抜ける。射線上にあった枝が数本、捻じ切られる音がした。<br>
「ふむ。威力は悪くなさそうだ」<br>
　しかし、その後何度か繰り返してみたものの、追撃の風を安定させられない。威力を高めることはできても、狙った方向に風が行くようにするのには時間が掛かりそうだ。<br>
「…聖火を操るようにはいかぬな」<br>
　昨晩に続き今日もまた新たな技を試してみたが、実戦で使うには練度が足りぬ。そして私たちには時間が無い。そのため、今は新たな技の習得に費やすよりも使える技を磨き上げる方が良さそうだ、という結論に落ち着いた。<br>
「…………。」<br>
　ふと見上げた頭上は葉に覆われ、その間から星が覗いていた。ここで『ジャンプ』をしたら、上空から着地点を定めるのは至難の業だろう。つまり、模擬訓練に適していると言える。<br>
　今後、こういった場所での戦闘が起こる可能性は十分にある。その際“手”が一つ封じられるのは避けたい。<br>
　上空から見定めるのが難しいならば……わかるようにしておけば良い。<br>
　相手が魔物ならばその独特な気配を目印とすれば問題ないが、人間や異界の存在だった場合、あるいは魔物の気配が変質していたり気配そのものが薄い場合、正確に追えなくなるだろう。<br>
　しかし私には、どのような場合においても確実に感知できるものが一つある。<br>
「――青き炎よ」<br>
　穂先に聖火を纏わせ、それを離れたところにある岩に向かって放つ。聖火は岩を取り囲み、絶えることなく揺らめいている。<br>
　その様子を見届け、高く跳躍した。<br>
　木々を越え、身体で空を切る感覚は存外心地好い。特に上昇から降下に移る際のふわりと浮く瞬間は、視界が一気に広がり、鳥にでもなったかのように錯覚する。<br>
　あるいはこれが竜の見る世の姿か。<br>
　そんな感慨に耽ることができるのもたった一瞬。次の瞬間には月光を背に、地上の聖火へ向かって急降下を始めている。<br>
　威力を増すために風魔法で速度を上げ、一直線にその中心へと槍を突き刺せば――予想以上の音と地を揺るがす衝撃が響き、岩は砕け散った。<br>
「ふむ、聖火を使うのは有効だな」<br>
　立ち込める土埃を風で払いながら思案する。降下に移るあの一瞬、本来であれば狙いを定める瞬間でもあるのだが、聖火の気を辿れば目標が見えずとも当てられよう。<br>
　要となる聖火は敵に悟られぬよう配すべきだな。背後…否、足元か？　着地と同時に炎を拡げれば槍が通じにくい敵にもいくらかダメージが入るだろう。<br>
　時間があればもう何度か試したいところだったが、そろそろ交代の頃合いだ。試行はまた次の機会だな。<br>
<br>
　そうして戻った私を出迎えたのは、心配そうな顔をしたセイルたちだった。<br>
「良かった、おかえりサザントス」<br>
「サザントスさん、ご無事ですか？　お怪我はされてませんか？」<br>
「白魔法は？　ケアルかけましょうか？！」<br>
「オフィーリア、アグネア。サザントスが困ってるから。落ち着いてくれ」<br>
　セシルに宥められ、詰め寄ってきていた女性陣二人が我に返る。<br>
「そなたらは先程の音で目を覚ましたのか」<br>
「うん。でもあなたの姿が見えなくて、セイルに聞いたら鍛錬に行ってるってことだったから。おそらく鍛錬の音だろうな、とは思っていたんだけど」<br>
「そうじゃなかったら、って思ったら不安になってしまって……。もう一度眠るなんてできなくて」<br>
「アグネアなんて林に突撃していきそうだったね」<br>
「だ、だってすごい音だったし地面もすごい揺れたじゃない！　もしサザントスさんが一人で魔物と戦ってたら、怪我してたらって考えたら…！」<br>
　私はそこらの魔物に後れを取る程未熟ではない――が<br>
「心配を掛けてすまなかった。少々鍛錬に熱が入り過ぎたようだ」<br>
「本当にどこも怪我してないんですよね？」<br>
「ああ」<br>
「良かったぁ」<br>
　文字通り胸を撫で下ろし安堵に頬を綻ばせるアグネア。その隣ではオフィーリアが同じように微笑みながら頷いている。<br>
　セイルとセシルも「何事も無くて良かった」と話し合っており、私はその様子をどこか他人事に眺めていた。<br>
　セイルは“選ばれし者”、オフィーリアはヨーセフ大司教の息女であり神官。この二人がそうなのはわかるが、セシルとアグネアもまたお人好しであるようだ。あるいはクリスタルがそういった者を選んだのか……。<br>
　否、今考えることではないな。<br>
<br>
「夜明けはまだ遠い。火の番は予定通り私が務める、そなたらはもう一度眠るがいい」<br>
「え……うーん、眠気覚めちゃってるんですよね」<br>
「あ、それならお話ししませんか？　童話とか、おとぎ話とか、アグネアさんが知ってるお話聞いてみたいです」<br>
「いいね！　オフィーリアのも聞かせてほしいな」<br>
「はい」<br>
　それでは、と寝に戻る二人を見送り、残るもう二人に目を向ける。<br>
「おれは寝られそう。なんかいろいろ起きすぎて、一周回って疲れたと言うか」<br>
「大物だな、セイル」<br>
「そんなことないと思うけど…セシルは？」<br>
「僕も眠るよ。少しでも戦いに備えておきたいからね」<br>
「そっか。じゃあ火をよろしく、サザントス」<br>
「承知した」<br>
　欠伸を噛み殺しながら横になるセイルに対し、セシルは何かを考え込んだままだ。<br>
　どうしたのかと問おうとすると、まっすぐな眼差しで名を呼んできた。<br>
「本当に大丈夫かい？」<br>
「……？　見ての通り、怪我もしていない」<br>
「もし――」<br>
　一瞬伏せられたセシルの目は、思い違いでなければ悲しみを宿しているように見えた。<br>
「もし、何か悩んでいることがあれば、話してほしい。どんなことでもかまわないから」<br>
「………。」<br>
「僕は異界の者でこの世界に詳しくない。それでも僕らは今共に旅をしていて、同じ火を囲んでいる。…すれ違う前に、違う道を行く前に、話し合うことができるんだ」<br>
「…この力を振るったと言う、友の話か」<br>
　セシルは肯定も否定もせず、儚い笑みを浮かべた。<br>
「一人で思い悩んでほしくないんだ。たった一人で下す決断は、誰かが悲しい思いをすることが多いから」<br>
「その思いは受け取っておこう」<br>
「頑固なんだな、あなたも」<br>
　それはたまに言われる。<br>
「…セシル、眠らぬならば稽古の相手でもしてもらおうか？」<br>
「はは、眠るよ。これ以上あなたを疲れさせたくないからね」<br>
　それじゃあおやすみ、と横になり十数秒後、静かな寝息が聞こえてきた。疲れているのはどちらだと言うのか。<br>
<br>
　頭上では星々が瞬いている。そこから視線をずらせば、月がより眩い光を地上へ投げかけていた。<br>
　今宵の月は獣が引っ搔いたような影を持つ、満ちぬ月。<br>
　その光と影に受けながら、私は四人の眠りを見守っていた――`
