　けれど幸いなことに彼女の目的は知れている。『人探し』だ。<br>
「彼女が辺獄で探す人物……か」<br>
　考えられる人が一人だけいる。でも正直この予想は外れていてほしい。外れたらいよいよどこを探せばいいのかわからなくなるけれど、それでも――…。<br>
「…行こう」<br>
　これから向かう先に彼女がいてほしい、でもその理由は外れていてほしい。そんな思いで、もはや懐かしい悔恨の間を踏みしめた。<br>
<br>
　一人で進む辺獄は、思うよりも険しかった。<br>
　聖火を灯し続ける必要があるというのもそうだけれど、魔物が際限なく湧いて出て行く手を阻んでくる。<br>
　ただ、統率する者がもういないからなのか、亡者が襲い掛かってくることはなかった。<br>
　この道を彼女も進んだのだろうか。たった一人、“誰か”を捜して。<br>
　辺獄に満ちるのは瘴気だけじゃない。怨み、憎しみ、怒り、悲しみ……心を蝕むあらゆる感情が渦巻いている。<br>
　明けない夜が続く世界でこんな空気に晒され続けていたら、普通の人は耐えられない。<br>
　辺獄と地上の時間の流れ方が同じだとしたら、彼女がここに来て三日は経っている筈だ。指輪を持たない彼女は普通の人と変わらない、何の対策もせず生者として三日を過ごすのは厳しいだろう。<br>
　それでも…手遅れだなんて考えたくない。<br>
「ここにもいなかった…。深奥まで行ってしまったのか…？」<br>
