「っ……」<br>
「なかないで、ロンド…。せいか、しゅしちょう、を…、つぐんでしょう…？」<br>
「無理ですよ……。あの人を喪って、今あなたまでこんな状態で…！」<br>
「…やさしい、ね、……でも、それぐらい、した…みが、ある………が……ひとり、に……、なら…くて…、………」<br>
