「…………。」<br>
「…目を……開けて、ください……」<br>
　頬に手を添えても起きてくれない。深く寝入ってしまったようだ。辺獄の地を聖火も指輪もなく進んできたのだから、いい加減疲労が溜まっていたのだろう。仕方ない、今は寝かせてあげよう。劇場まで戻れば休めるかな。<br>
