　“否”だ。それぐらいこの痛みは耐え難く、そしてこの痛み以上にこの世の仕組みが許し難かった。<br>
「若きレイヴァースよ、そなたが“禁記”に気付けたなら――」<br>
　その時こそ、この世界を変えられるかも知れない。<br>
　そう思っても口に出せなかった。どこで“奴”が聞いているかわからないからだ。<br>
　回収を逃れた“ロンディミア旅行記”は、もう何冊も残っていない。そしてアレファンが持っていたものが最も状態の良い一冊。損傷すれば、あるいは奪われれば、希望は絶たれる。<br>
　これは賭けなのだ。真の平穏を賭け投じられた一石。<br>
　些かの不安はあるが、レイヴァースの娘は兄より聡明と聞く。あるいは兄ではなく妹の方が気付くかも知れない。<br>
　そして彼らの近くに教会と縁深い者がいるという事実。もはや世界が真実に気付かせんとしているようにも感じられる。それにあの者らは……“彼女”の縁者だ、これを偶然と呼ぶのはあまりに出来すぎている。<br>
　出来すぎているから、“奴”に仕組まれているのかと警戒し、エベルに調査を頼んだこともあった。が……本当によく出来た偶然という結果に落ち着いた。<br>
「この賭けに負けたら、その時こそ我らは“奴”に膝を屈することになるのだろうな」<br>
　何も知らぬ若者に世の命運を託す心苦しさはある、しかし何も知らぬからこそ“奴”の目を逃れられているのだ。<br>
　あの者が“禁記”に気付き、動き始めるなら……ミトスはその原動力になる。<br>
　だからミトスには生きていてもらわねばならぬのだ。<br>
　彼らが真実へと走るために。真実に辿り着くまでこの世を延命させておくために。<br>
「……こんな理由であの子の生を望む私が、どうして“父”を名乗れよう」<br>
　それにあの子には本当の父がいる。あの者を差し置いて私が父を名乗るなど許されぬことだ。<br>
　だからこれは、ただあの子の保護者として。<br>
<br>
　慎重にドアを開けると、廊下の明かりが足元から細く伸びていく。<br>
　最低限の幅だけ開いたドアを抜け、足音を立てぬよう進む。例え物音や光で目を覚ましたとて、再び眠らせることなど造作もないのだが、毎年この時間は独特の緊張感に包まれ落ち着かぬ。<br>
「ん………ぅ…」<br>
「！」<br>
「……すぅ…」<br>
「…………。」<br>
