　保護した直後を除けば、ミトスは眠りの深い子だった。使者の真似事をした最初の年以外、贈り物を置く前に彼女が目覚めたことは無い。だからといって今年も眠っていてくれるとは限らぬのだが。<br>
　ミトスの枕元には彼女の“友人”がいる。彼女が級友から貰ったものや私が贈ったもので、その全てにミトスは名前を付けている。そのうちの一体、真っ白な犬の人形に小箱を持たせた。確か、名は……<br>
「……スズ、そなたにこれの守護を任せよう。最も重要な任と心得よ」<br>
　廊下から差し込む光が反射し、承知したと言わんばかりにスズの青い目が煌めいた。<br>
　本当に奪われるわけにはゆかぬため、念には念を入れ、スズごと守護魔法と反射魔法を掛けておく。……力を奪われた今の私には、このぐらいしかしてやれぬのが悔やまれる。<br>
　ミトスが“眠る”まで、およそ三ヶ月弱……それまでに指輪が馴染めば、この戦いの勝率は跳ね上がる。<br>
