　と言いつつもう一口。鼻を抜ける香りが良く、ミルクとのバランスも丁度良い。深いコクを味わいつつ飲み込めば、甘い香りがまた立ち上る。<br>
「……これは良い」<br>
「ふふ。よければこちらもどうぞ」<br>
　とミトスが前に置いたのは、色白の単純なクッキーが乗った皿。<br>
「ナッツクッキーです。香ばしくておいしいですよ」<br>
「しかし、それはそなたが頼んだものだろう？」<br>
