　押し寄せるその濁流を、グランポートは排さなかった。彼らが訪れた理由が必ずしも言葉通りでないことは承知の上で受け入れ、利権を掠め取ろうとする醜き欲すら呑み込んで……最後には己が一部としてみせたのだ。<br>
