    url: "https://erla.jp/fwfw_watage/novel/761697/976630/",
    keywords: `　世界の在り方をめぐる戦いで“選ばれし者”に敗れたサザントス。<br>
　力を使い果たし消える筈だった彼を消滅から救ったのもまた、“選ばれし者”だった。<br>
<br>
　希望は灯れど安定にはまだ遠い世界を暗き欲から守るために、谷底に沈ませないために、サザントスは差し出された手を取った。<br>
<br>
　聖火守指長と選ばれし者というかつての関係性とは異なり、ただ一介の剣士と旅人として大陸を回る日々。<br>
　騒動に巻き込まれる日もあるが基本的には静かな旅路、そして共に在る選ばれし者の穏やかさは、彼の心境に変化を齎した。<br>
　その変化に最初は戸惑い混乱したものの、落ち着いて己の心に問いかけ――受け入れた。<br>
<br>
　これは平穏な時を過ごすサザントスとミトスの、ある日のお話。`
