　そして祈るように目を閉じ、紡ぐ。<br>
「“青き炎は我が魂、我が守り人なり”――」<br>
　聖き炎が剣を包み周囲を照らす。その温もりを迎え入れるように広げられた手の先で、空っぽのランタンが青い光を返す。<br>
