　その青い輝きの向こうから覗く瞳は苦しそうに揺らぎ、そうして交わる視線に、サザントスは「…ああ」と呟いた。<br>
「…わかった。今、楽にしてやろう」<br>
「なっ…待ってくださいサザントスさん！！」<br>
