とても強い祈りの力を持っている。祈る時に一切の雑念が混じらず、雑念を遮断して祈る姿勢に入る速さが尋常ではない。<br>
<br>
―――――――――――――――――――――<br>
蛇足おぶ蛇足<br>
<br>
【パラメータ：高い順】<br>
属攻＞会心＞SP＞属防＞回避＞速度＞HP＞物防＞物攻<br>
　※盗賊ジョブとしては遅い方だがラース相手に先手を取れるくらいの速度はある<br>
　※弱い物攻を高い会心と手数で補う<br>
　※ミトス自身は魔法を使えないが、旅の中で属攻を活かせるアビリティを身につける<br>
<br>
【アビリティ傾向】<br>
短剣と弓。<br>
